    while i < len(sql):
        ch = sql[i]
        if ch == "?":
            out.append(f"${n}")
            n += 1
            i += 1
        elif ch in ("'", '"'):
            out.append(ch)
            i += 1
            while i < len(sql):
                out.append(sql[i])
                if sql[i] == ch and sql[i - 1] != "\\":
